mas-cpu:
cat > /home/learner/aso/p31/mas-cpu.sh <<'ASO_EOF'
#!/bin/bash
(($#>1)) && { echo "uso: mas-cpu.sh [N]" >&2; exit 1; }
n=${1:-5}
[[ ! $n =~ ^0*[1-9][0-9]*$ ]] && { echo "N debe ser un entero positivo" >&2; exit 2; }
ps -eo pid,comm,time --no-headers --sort -time | head -n "$n"
exit 0
ASO_EOF
chmod 755 /home/learner/aso/p31/mas-cpu.sh
chown learner:learner /home/learner/aso/p31/mas-cpu.sh

antiguos:
cat > /home/learner/aso/p31/antiguos.sh <<'ASO_EOF'
#!/bin/bash
(($#>1)) && { echo "uso: antiguos.sh [N]" >&2; exit 1; }
n=${1:-10}
[[ ! $n =~ ^0*[1-9][0-9]*$ ]] && { echo "N debe ser un entero positivo" >&2; exit 2; }
ps -eo pid,comm,time,etime --no-headers --sort start_time | head -n "$n"
exit 0
ASO_EOF
chmod 755 /home/learner/aso/p31/antiguos.sh
chown learner:learner /home/learner/aso/p31/antiguos.sh

estado:
cat > /home/learner/aso/p31/estado.sh <<'ASO_EOF'
#!/bin/bash
(($#!=1)) && { echo "uso: estado.sh ESTADO" >&2; exit 1; }
[[ ! $1 =~ ^[A-Z][A-Za-z\<+]*$ ]] && { echo "estado no válido" >&2; exit 2; }
lista=$(ps -eo pid,user,stat --no-headers | awk -v e="$1" '$3==e')
echo "${lista:-ninguno}"
exit 0
ASO_EOF
chmod 755 /home/learner/aso/p31/estado.sh
chown learner:learner /home/learner/aso/p31/estado.sh

hijos:
cat > /home/learner/aso/p31/hijos.sh <<'ASO_EOF'
#!/bin/bash
(($#!=1)) && { echo "uso: hijos.sh PID" >&2; exit 1; }
[[ ! $1 =~ ^[0-9]+$ ]] && { echo "el PID debe ser un número" >&2; exit 2; }
[[ ! -d /proc/$1 ]] && { echo "el proceso no existe" >&2; exit 4; }
lista=$(ps --ppid "$1" -o pid,comm --no-headers --sort pid)
echo "${lista:-sin hijos}"
exit 0
ASO_EOF
chmod 755 /home/learner/aso/p31/hijos.sh
chown learner:learner /home/learner/aso/p31/hijos.sh
